// Paid orders ship only when no hold is on record. An unverified address
// derives a hold for order 2, so only order 1 ships. The shipping rule is
// written first to show that stratification settles holds before negation.
//
// Compiled from examples/n3-scoped-negation.n3 with n3-interchange 0.1.4.
// The generated program below runs directly in eyemind and the playground.

// Generated by n3-interchange from examples/n3-scoped-negation.n3.
// Each N3 triple is rdf(Subject, Predicate, Object). Without a log:query
// the conclusions are the triples the forward rules derive.
fact(rdf(iri("https://example.org/orders#order1"), iri("https://example.org/orders#status"), iri("https://example.org/orders#paid")))
fact(rdf(iri("https://example.org/orders#order2"), iri("https://example.org/orders#status"), iri("https://example.org/orders#paid")))
fact(rdf(iri("https://example.org/orders#order2"), iri("https://example.org/orders#address"), iri("https://example.org/orders#unverified")))
fact(rdf(iri("https://example.org/orders#order3"), iri("https://example.org/orders#status"), iri("https://example.org/orders#open")))
implies([rdf(Order, iri("https://example.org/orders#status"), iri("https://example.org/orders#paid")), not(rdf(Order, iri("https://example.org/orders#hold"), _1))], rdf(Order, iri("https://example.org/orders#action"), iri("https://example.org/orders#ship")))
implies(rdf(Order, iri("https://example.org/orders#address"), iri("https://example.org/orders#unverified")), rdf(Order, iri("https://example.org/orders#hold"), iri("https://example.org/orders#addressCheck")))
